"""Regenerate Formula/portpilot.rb and packaging/aur/PKGBUILD for a released version.

The sdist URL and hash come from PyPI; the Homebrew resources are the runtime
dependency closure pinned in uv.lock. Standard library only.

    python3 .github/scripts/bump_packaging.py --version 0.3.0
"""

from __future__ import annotations

import argparse
import json
import re
import time
import urllib.error
import urllib.request
from pathlib import Path

import tomllib

ROOT = Path(__file__).resolve().parents[2]
FORMULA = ROOT / "Formula" / "portpilot.rb"
PKGBUILD = ROOT / "packaging" / "aur" / "PKGBUILD"

FORMULA_TEMPLATE = """\
# Homebrew formula for PortPilot.
#
#   brew tap cyber-emreclskn/portpilot https://github.com/cyber-emreclskn/portpilot
#   brew install portpilot
#
# Generated by .github/scripts/bump_packaging.py on every release; edit the
# template there, not this file.
class Portpilot < Formula
  include Language::Python::Virtualenv

  desc "Interactive terminal port manager: list, inspect and kill listening ports"
  homepage "https://github.com/cyber-emreclskn/portpilot"
  url "{url}"
  sha256 "{sha256}"
  license "MIT"

  depends_on "python@3.13"

{resources}

  def install
    virtualenv_install_with_resources
  end

  test do
    assert_match version.to_s, shell_output("#{{bin}}/portpilot --version")
  end
end
"""


def pypi_sdist(version: str, attempts: int = 10, delay: float = 15.0) -> tuple[str, str]:
    """Return (url, sha256) of the sdist, waiting for PyPI to list a fresh upload."""
    api = f"https://pypi.org/pypi/portpilot/{version}/json"
    for attempt in range(attempts):
        try:
            with urllib.request.urlopen(api, timeout=30) as response:
                data = json.load(response)
            for file in data["urls"]:
                if file["packagetype"] == "sdist":
                    return file["url"], file["digests"]["sha256"]
        except urllib.error.HTTPError as exc:
            if exc.code != 404:
                raise
        if attempt < attempts - 1:
            time.sleep(delay)
    raise SystemExit(f"portpilot {version} has no sdist on PyPI")


def runtime_resources(lock_path: Path) -> list[tuple[str, str, str]]:
    """Runtime dependency closure from uv.lock as (name, sdist url, sha256)."""
    packages = {p["name"]: p for p in tomllib.loads(lock_path.read_text())["package"]}
    seen: set[str] = set()
    stack = [d["name"] for d in packages["portpilot"]["dependencies"]]
    while stack:
        name = stack.pop()
        if name in seen:
            continue
        seen.add(name)
        for dep in packages[name].get("dependencies", []):
            if "win32" in dep.get("marker", ""):
                continue  # Homebrew is macOS/Linux only
            stack.append(dep["name"])
    resources = []
    for name in sorted(seen):
        sdist = packages[name]["sdist"]
        resources.append((name, sdist["url"], sdist["hash"].removeprefix("sha256:")))
    return resources


def render_formula(url: str, sha256: str, resources: list[tuple[str, str, str]]) -> str:
    blocks = [
        f'  resource "{name}" do\n    url "{res_url}"\n    sha256 "{res_sha}"\n  end'
        for name, res_url, res_sha in resources
    ]
    return FORMULA_TEMPLATE.format(url=url, sha256=sha256, resources="\n\n".join(blocks))


def bump_pkgbuild(text: str, version: str, sha256: str) -> str:
    text = re.sub(r"^pkgver=.*$", f"pkgver={version}", text, flags=re.MULTILINE)
    text = re.sub(r"^pkgrel=.*$", "pkgrel=1", text, flags=re.MULTILINE)
    text = re.sub(r"^sha256sums=.*$", f"sha256sums=('{sha256}')", text, flags=re.MULTILINE)
    return re.sub(r'"portpilot [0-9][^"]*"', f'"portpilot {version}"', text)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--version", required=True, help="released version, e.g. 0.3.0 or v0.3.0")
    args = parser.parse_args()
    version = args.version.removeprefix("v")

    url, sha256 = pypi_sdist(version)
    FORMULA.write_text(render_formula(url, sha256, runtime_resources(ROOT / "uv.lock")))
    PKGBUILD.write_text(bump_pkgbuild(PKGBUILD.read_text(), version, sha256))
    print(f"Packaging files updated for portpilot {version}")


if __name__ == "__main__":
    main()
